label("\tiny{less than 10,000}",(-30,-15),S);
label("\tiny{100,000 or more}",(30,-15),S);
label("\tiny{residents}",(30,13),N);
label("\tiny{residents}",(-30,-17),S);
label("\tiny{residents}",(30,-17),S);
[/asy]

